<template>
  <PageShell title="现场控制塔" description="把设备停机、生产异常、责任动作和 SLA 逾期统一到一个可追溯闭环。">
    <template #actions>
      <button class="button button-ghost" @click="load">↻ 刷新</button>
      <button class="button button-ghost" @click="showDowntime = true">＋登记停机</button>
      <button class="button button-primary" @click="showException = true">＋上报异常</button>
    </template>

    <div class="ops-kpis">
      <div><span>未关闭异常</span><b>{{ summary.openExceptions ?? 0 }}</b><small>含 {{ summary.criticalExceptions ?? 0 }} 条关键异常</small></div>
      <div><span>逾期责任动作</span><b class="danger">{{ summary.overdueActions ?? 0 }}</b><small>需要升级或重新分派</small></div>
      <div><span>今日停机</span><b>{{ summary.downtimeMinutesToday ?? 0 }}<em>min</em></b><small>当前未恢复 {{ summary.openDowntime ?? 0 }} 起</small></div>
      <div><span>设备风险</span><b class="warning">{{ summary.equipmentAtRisk ?? 0 }}</b><small>{{ summary.equipmentCount ?? 0 }} 台在册设备</small></div>
    </div>

    <div class="subnav ops-tabs">
      <button v-for="item in tabs" :key="item.key" class="subnav-item" :class="{ active: tab === item.key }" @click="tab = item.key">{{ item.label }} <span v-if="item.count !== undefined">{{ item.count }}</span></button>
    </div>

    <section v-if="tab === 'exceptions'" class="panel">
      <div class="panel-heading"><div><h3>异常闭环台账</h3><p>状态必须按 OPEN → ACKNOWLEDGED → CONTAINED → RESOLVED → CLOSED 流转，关闭前必须完成责任动作。</p></div><label class="live-filter"><i></i>实时数据</label></div>
      <div class="filter-row"><select v-model="exceptionStatus" @change="loadExceptions"><option value="">全部状态</option><option v-for="item in statusOptions" :key="item.value" :value="item.value">{{ item.label }}</option></select><select v-model="exceptionPriority" @change="loadExceptions"><option value="">全部优先级</option><option v-for="item in priorityOptions" :key="item.value" :value="item.value">{{ item.label }}</option></select><input v-model="exceptionKeyword" placeholder="搜索异常号、标题、设备或工单" @keyup.enter="loadExceptions" /><button class="button button-ghost" @click="loadExceptions">筛选</button><span class="filter-spacer"></span><span class="filter-note">共 {{ exceptions.length }} 条</span></div>
      <DataTable :columns="exceptionColumns" :rows="exceptions" :show-toolbar="true" :enable-export="true" :enable-column-settings="true" :pagination="true" table-title="异常清单" table-hint="优先级、责任人、SLA 与动作数均来自现场控制塔" export-name="polaris-exceptions">
        <template #actions="{ row }"><button class="table-action" @click="selectException(row)">查看闭环</button><button v-if="nextStatus(row.status)" class="table-action" @click="advance(row)">{{ nextStatusLabel(row.status) }}</button></template>
      </DataTable>
      <div v-if="selectedException" class="ops-detail">
        <div class="detail-heading"><div><span class="eyebrow">EXCEPTION / {{ selectedException.exception_no }}</span><h3>{{ selectedException.title }}</h3><p>{{ selectedException.description }}</p></div><div class="detail-actions"><span :class="['ops-status', `ops-status--${String(selectedException.status).toLowerCase()}`]">{{ statusLabel(selectedException.status) }}</span><button class="button button-ghost" @click="selectedException = null">收起</button></div></div>
        <div class="detail-meta"><span><small>优先级</small><b :class="priorityTone(selectedException.priority)">{{ priorityLabel(selectedException.priority) }}</b></span><span><small>责任人</small><b>{{ selectedException.owner_code || '待分派' }}</b></span><span><small>关联对象</small><b>{{ selectedException.equipment_code || selectedException.work_order_no || selectedException.source_ref || '现场上报' }}</b></span><span><small>SLA 截止</small><b :class="{ danger: isOverdue(selectedException) }">{{ formatDate(selectedException.due_at) }}</b></span><span><small>未完成动作</small><b>{{ selectedException.open_action_count || 0 }}</b></span></div>
        <div class="action-heading"><div><h4>责任动作</h4><small>每个动作必须有负责人和截止时间，完成后才能关闭异常。</small></div><button class="button button-ghost" @click="showAction = true">＋添加动作</button></div>
        <div class="action-list"><div v-for="action in actions" :key="action.id" class="action-row"><span class="action-marker" :class="{ done: action.status === 'COMPLETED' }">{{ action.status === 'COMPLETED' ? '✓' : '!' }}</span><div><b>{{ action.action_description }}</b><small>{{ action.action_type }} · {{ action.owner_code || '待分派' }} · 截止 {{ formatDate(action.due_at) }}</small></div><button v-if="action.status !== 'COMPLETED'" class="table-action" @click="completeAction(action)">完成</button><span v-else class="action-done">已完成</span></div><div v-if="!actions.length" class="empty-operation">暂无责任动作，建议先完成围堵、分析和恢复动作拆解。</div></div>
      </div>
    </section>

    <section v-else-if="tab === 'equipment'" class="panel">
      <div class="panel-heading"><div><h3>设备健康与维护窗口</h3><p>设备状态由现场心跳、停机事件和维护计划共同驱动。</p></div><button class="button button-primary" @click="showEquipment = true">＋新增设备</button></div>
      <div class="equipment-grid"><article v-for="item in equipment" :key="item.id" class="equipment-card"><div class="equipment-top"><span class="equipment-icon">◈</span><div><b>{{ item.equipment_name }}</b><small>{{ item.equipment_code }} · {{ item.work_center || '未分配工作中心' }}</small></div><span :class="['equipment-status', `equipment-status--${String(item.status).toLowerCase()}`]">{{ equipmentStatusLabel(item.status) }}</span></div><div class="health-bar"><span :style="{ width: `${Math.max(0, Math.min(100, item.health_score || 0))}%` }"></span></div><div class="equipment-meta"><span>健康度 <b>{{ item.health_score }}%</b></span><span>下次保养 <b>{{ formatDate(item.next_maintenance_at) }}</b></span></div><div class="equipment-foot"><span>{{ item.current_work_order ? `当前工单 ${item.current_work_order}` : '当前无工单' }}</span><button class="table-action" @click="openEquipmentDowntime(item)">登记停机</button></div></article><div v-if="!equipment.length" class="empty-operation">暂无设备档案，请先新增设备。</div></div>
    </section>

    <section v-else class="panel">
      <div class="panel-heading"><div><h3>停机事件与恢复记录</h3><p>停机登记会自动把设备置为 DOWN，并创建一条 EQUIPMENT 异常；恢复不会绕过根因分析。</p></div><button class="button button-primary" @click="showDowntime = true">＋登记停机</button></div>
      <DataTable :columns="downtimeColumns" :rows="downtime" :show-toolbar="true" :enable-export="true" :enable-column-settings="true" :pagination="true" table-title="停机事件" export-name="polaris-downtime"><template #actions="{ row }"><button v-if="row.status === 'OPEN'" class="table-action" @click="resume(row)">确认恢复</button><span v-else class="action-done">已恢复 {{ row.duration_minutes || 0 }} min</span></template></DataTable>
    </section>

    <AppModal v-model="showException" title="上报现场异常" subtitle="先记录事实和影响，再通过责任动作完成闭环。" confirm-text="提交异常" @confirm="saveException">
      <div class="ops-form"><label>异常标题<input v-model.trim="exceptionForm.title" required placeholder="例如：工位扫码器连续失败" /></label><label>异常分类<select v-model="exceptionForm.category"><option value="PROCESS">生产过程</option><option value="MATERIAL">物料齐套</option><option value="QUALITY">质量风险</option><option value="EQUIPMENT">设备异常</option><option value="SAFETY">安全事件</option></select></label><label>优先级<select v-model="exceptionForm.priority"><option v-for="item in priorityOptions" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>责任人<input v-model.trim="exceptionForm.ownerCode" placeholder="计划员 / 设备员 / 仓库员" /></label><label>关联工单<input v-model.trim="exceptionForm.workOrderNo" placeholder="可选：WO-..." /></label><label>影响数量<input v-model.number="exceptionForm.impactQty" type="number" min="0" placeholder="0" /></label><label class="full">异常描述<textarea v-model.trim="exceptionForm.description" rows="4" required placeholder="记录发生时间、现场事实、影响范围和临时措施"></textarea></label><label class="full">SLA 截止<input v-model="exceptionForm.dueAt" type="datetime-local" /></label></div>
    </AppModal>
    <AppModal v-model="showAction" title="添加责任动作" subtitle="责任动作是关闭异常的门禁。" confirm-text="保存动作" @confirm="saveAction"><div class="ops-form"><label class="full">动作描述<textarea v-model.trim="actionForm.actionDescription" rows="3" placeholder="例如：隔离在制品并完成首件复测" required></textarea></label><label>动作类型<select v-model="actionForm.actionType"><option value="CONTAINMENT">围堵</option><option value="ROOT_CAUSE">根因分析</option><option value="RECOVERY">恢复</option><option value="PREVENTION">预防</option></select></label><label>负责人<input v-model.trim="actionForm.ownerCode" placeholder="责任人账号" /></label><label class="full">截止时间<input v-model="actionForm.dueAt" type="datetime-local" /></label></div></AppModal>
    <AppModal v-model="showDowntime" title="登记设备停机" subtitle="系统会自动创建现场异常并将设备状态置为 DOWN。" confirm-text="登记停机" @confirm="saveDowntime"><div class="ops-form"><label>设备<select v-model="downtimeForm.equipmentCode"><option value="" disabled>请选择设备</option><option v-for="item in equipment" :key="item.id" :value="item.equipment_code">{{ item.equipment_name }} · {{ item.equipment_code }}</option></select></label><label>停机原因<input v-model.trim="downtimeForm.reasonCode" placeholder="例如：ELECTRICAL / MATERIAL_WAIT" /></label><label>原因名称<input v-model.trim="downtimeForm.reasonName" placeholder="例如：电气故障" /></label><label>严重度<select v-model="downtimeForm.severity"><option value="MEDIUM">一般</option><option value="HIGH">高</option><option value="CRITICAL">关键</option></select></label><label class="full">现场描述<textarea v-model.trim="downtimeForm.description" rows="3" placeholder="记录报警、设备现象和临时处置"></textarea></label></div></AppModal>
    <AppModal v-model="showEquipment" title="新增设备档案" subtitle="设备编码是停机、维护与工单关联的稳定主键。" confirm-text="保存设备" @confirm="saveEquipment"><div class="ops-form"><label>设备编码<input v-model.trim="equipmentForm.equipmentCode" placeholder="例如：ASM-03" /></label><label>设备名称<input v-model.trim="equipmentForm.equipmentName" placeholder="例如：三线总装工位" /></label><label>工作中心<input v-model.trim="equipmentForm.workCenter" placeholder="例如：装配三线" /></label><label>型号<input v-model.trim="equipmentForm.model" placeholder="可选" /></label><label>初始状态<select v-model="equipmentForm.status"><option value="RUNNING">运行</option><option value="IDLE">空闲</option><option value="MAINTENANCE">保养中</option></select></label><label>健康度<input v-model.number="equipmentForm.healthScore" type="number" min="0" max="100" /></label><label class="full">下次保养<input v-model="equipmentForm.nextMaintenanceAt" type="datetime-local" /></label></div></AppModal>
  </PageShell>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import PageShell from '../components/PageShell.vue'
import DataTable from '../components/DataTable.vue'
import AppModal from '../components/AppModal.vue'
import { request } from '../api'

function notify(message, type = 'error') { window.dispatchEvent(new CustomEvent('polaris:toast', { detail: { message, type } })) }

const tab = ref('exceptions'); const summary = ref({}); const exceptions = ref([]); const equipment = ref([]); const downtime = ref([]); const selectedException = ref(null); const actions = ref([])
const exceptionStatus = ref(''); const exceptionPriority = ref(''); const exceptionKeyword = ref(''); const showException = ref(false); const showAction = ref(false); const showDowntime = ref(false); const showEquipment = ref(false)
const exceptionForm = ref({ title: '', category: 'PROCESS', priority: 'MEDIUM', ownerCode: '', workOrderNo: '', impactQty: 0, description: '', dueAt: '' })
const actionForm = ref({ actionType: 'CONTAINMENT', actionDescription: '', ownerCode: '', dueAt: '' })
const downtimeForm = ref({ equipmentCode: '', reasonCode: '', reasonName: '', severity: 'MEDIUM', description: '' })
const equipmentForm = ref({ equipmentCode: '', equipmentName: '', workCenter: '', model: '', status: 'RUNNING', healthScore: 100, nextMaintenanceAt: '' })
const statusOptions = [{ value: 'OPEN', label: '待确认' }, { value: 'ACKNOWLEDGED', label: '已确认' }, { value: 'CONTAINED', label: '已围堵' }, { value: 'RESOLVED', label: '已解决' }, { value: 'CLOSED', label: '已关闭' }]
const priorityOptions = [{ value: 'LOW', label: '低' }, { value: 'MEDIUM', label: '中' }, { value: 'HIGH', label: '高' }, { value: 'CRITICAL', label: '关键' }]
const tabs = computed(() => [{ key: 'exceptions', label: '异常闭环', count: summary.value.openExceptions || 0 }, { key: 'equipment', label: '设备健康', count: summary.value.equipmentAtRisk || 0 }, { key: 'downtime', label: '停机事件', count: summary.value.openDowntime || 0 }])
const exceptionColumns = [{ key: 'exception_no', label: '异常号' }, { key: 'title', label: '标题' }, { key: 'category', label: '分类', format: value => ({ PROCESS: '生产过程', MATERIAL: '物料', QUALITY: '质量', EQUIPMENT: '设备', SAFETY: '安全' }[value] || value) }, { key: 'priority', label: '优先级', status: true, format: priorityLabel }, { key: 'owner_code', label: '责任人' }, { key: 'due_at', label: 'SLA 截止', format: formatDate }, { key: 'status', label: '状态', status: true, format: statusLabel }, { key: 'open_action_count', label: '未完成动作' }]
const downtimeColumns = [{ key: 'event_no', label: '事件号' }, { key: 'equipment_name', label: '设备' }, { key: 'reason_name', label: '停机原因' }, { key: 'severity', label: '严重度', status: true, format: priorityLabel }, { key: 'started_at', label: '开始时间', format: formatDate }, { key: 'duration_minutes', label: '时长(min)' }, { key: 'status', label: '状态', status: true, format: value => value === 'OPEN' ? '未恢复' : '已恢复' }]

function statusLabel(value) { return statusOptions.find(item => item.value === value)?.label || value || '—' }
function priorityLabel(value) { return priorityOptions.find(item => item.value === value)?.label || value || '—' }
function priorityTone(value) { return ['CRITICAL', 'HIGH'].includes(value) ? 'danger' : value === 'MEDIUM' ? 'warning' : 'normal' }
function equipmentStatusLabel(value) { return ({ RUNNING: '运行', IDLE: '空闲', DOWN: '停机', MAINTENANCE: '保养', RETIRED: '退役' }[value] || value) }
function nextStatus(status) { return ({ OPEN: 'ACKNOWLEDGED', ACKNOWLEDGED: 'CONTAINED', CONTAINED: 'RESOLVED', RESOLVED: 'CLOSED' }[status] || '') }
function nextStatusLabel(status) { return ({ ACKNOWLEDGED: '确认', CONTAINED: '围堵完成', RESOLVED: '标记解决', CLOSED: '关闭异常' }[nextStatus(status)] || '推进') }
function formatDate(value) { if (!value) return '—'; return String(value).replace('T', ' ').slice(0, 16) }
function isOverdue(row) { return row.due_at && !['CLOSED', 'RESOLVED'].includes(row.status) && new Date(row.due_at) < new Date() }

async function load() { try { const [summaryData, exceptionData, equipmentData, downtimeData] = await Promise.all([request('/operations/summary'), request('/operations/exceptions'), request('/operations/equipment'), request('/operations/downtime')]); summary.value = summaryData || {}; exceptions.value = exceptionData || []; equipment.value = equipmentData || []; downtime.value = downtimeData || [] } catch (error) { notify(error.message) } }
async function loadExceptions() { try { exceptions.value = await request(`/operations/exceptions?status=${encodeURIComponent(exceptionStatus.value)}&priority=${encodeURIComponent(exceptionPriority.value)}&keyword=${encodeURIComponent(exceptionKeyword.value)}`) || [] } catch (error) { notify(error.message) } }
async function selectException(row) { try { selectedException.value = await request(`/operations/exceptions/${row.id}`); actions.value = selectedException.value.actions || [] } catch (error) { notify(error.message) } }
async function saveException() { try { await request('/operations/exceptions', { method: 'POST', body: JSON.stringify(exceptionForm.value) }); showException.value = false; exceptionForm.value = { title: '', category: 'PROCESS', priority: 'MEDIUM', ownerCode: '', workOrderNo: '', impactQty: 0, description: '', dueAt: '' }; await load() } catch (error) { notify(error.message) } }
async function advance(row) { const target = nextStatus(row.status); if (target === 'CLOSED' && !confirm('关闭前请确认所有责任动作已完成，是否继续？')) return; try { await request(`/operations/exceptions/${row.id}/transition`, { method: 'POST', body: JSON.stringify({ status: target }) }); await load(); if (selectedException.value?.id === row.id) await selectException(row) } catch (error) { notify(error.message) } }
async function saveAction() { if (!selectedException.value) return; try { await request(`/operations/exceptions/${selectedException.value.id}/actions`, { method: 'POST', body: JSON.stringify(actionForm.value) }); showAction.value = false; actionForm.value = { actionType: 'CONTAINMENT', actionDescription: '', ownerCode: '', dueAt: '' }; await selectException(selectedException.value); await load() } catch (error) { notify(error.message) } }
async function completeAction(action) { try { await request(`/operations/actions/${action.id}/complete`, { method: 'POST' }); await selectException(selectedException.value); await load() } catch (error) { notify(error.message) } }
async function saveDowntime() { try { await request('/operations/downtime', { method: 'POST', body: JSON.stringify(downtimeForm.value) }); showDowntime.value = false; downtimeForm.value = { equipmentCode: '', reasonCode: '', reasonName: '', severity: 'MEDIUM', description: '' }; await load(); tab.value = 'downtime' } catch (error) { notify(error.message) } }
function openEquipmentDowntime(item) { downtimeForm.value.equipmentCode = item.equipment_code; showDowntime.value = true }
async function resume(row) { try { await request(`/operations/downtime/${row.id}/resume`, { method: 'POST' }); await load() } catch (error) { notify(error.message) } }
async function saveEquipment() { try { await request('/operations/equipment', { method: 'POST', body: JSON.stringify(equipmentForm.value) }); showEquipment.value = false; equipmentForm.value = { equipmentCode: '', equipmentName: '', workCenter: '', model: '', status: 'RUNNING', healthScore: 100, nextMaintenanceAt: '' }; await load() } catch (error) { notify(error.message) } }
onMounted(load)
</script>

<style scoped>
