.action-heading small{color:#9aa9b6;font-size:9px}.action-list{background:#fff;border:1px solid #e7edf4;border-radius:7px}.action-row{display:flex;align-items:center;gap:10px;padding:12px 13px;border-bottom:1px solid #edf2f6}.action-row:last-child{border-bottom:0}.action-marker{width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:#fff1ed;color:#cc6c60;font-size:11px}.action-marker.done{background:#eaf8f1;color:#2eaa7b}.action-row>div{min-width:0;flex:1}.action-row b,.action-row small{display:block}.action-row b{font-size:10px;color:#456078}.action-row small{font-size:9px;color:#98a7b3;margin-top:4px}.action-done{font-size:9px;color:#30a77c}.equipment-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.equipment-card{border:1px solid #e5edf5;border-radius:9px;padding:15px;background:#fbfdff}.equipment-top{display:flex;gap:9px;align-items:flex-start}.equipment-icon{width:29px;height:29px;display:grid;place-items:center;border-radius:7px;background:#eaf2ff;color:#3b7ed3}.equipment-top>div{min-width:0}.equipment-top b,.equipment-top small{display:block}.equipment-top b{font-size:11px;color:#385570}.equipment-top small{font-size:9px;color:#99a8b4;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.equipment-status{margin-left:auto}.equipment-status--running{background:#eaf8f1;color:#2aa474}.equipment-status--idle{background:#edf4ff;color:#4782c7}.equipment-status--down{background:#fff0ed;color:#cb665a}.equipment-status--maintenance{background:#fff5df;color:#b68037}.health-bar{height:6px;background:#eaf0f4;border-radius:6px;overflow:hidden;margin:17px 0 8px}.health-bar span{height:100%;display:block;border-radius:6px;background:linear-gradient(90deg,#e4a05f,#38b98c)}.equipment-meta,.equipment-foot{display:flex;justify-content:space-between;gap:8px;color:#96a5b2;font-size:9px}.equipment-meta b{color:#4e667c;font-weight:600}.equipment-foot{align-items:center;border-top:1px solid #edf2f6;margin-top:12px;padding